<script setup>import AuroraSwitch from '../forms/AuroraSwitch.vue';defineProps({time:{required:true},name:{required:true},days:String,enabled:Boolean});defineEmits(['toggle','edit'])</script><template><article class="reminder" @click="$emit('edit')"><time>{{time}}</time><div><h3>{{name}}</h3><p>{{days}}</p></div><AuroraSwitch :model-value="enabled" @click.stop @update:model-value="$emit('toggle',$event)"/></article></template><style scoped>.reminder{display:flex;align-items:center;gap:14px;min-height:64px;padding:10px 0;border-bottom:1px solid var(--border-subtle)}time{color:var(--text-primary);font:500 18px var(--font-numeric)}.reminder>div{flex:1}h3{color:var(--text-primary);font:600 14px var(--font-core)}p{margin-top:3px;color:var(--text-muted);font:400 12px var(--font-core)}</style>
